      NextStep=4,
      RoleImg="1001001",
      RolePos=3,
      StartFun="",
      Type="角色出现",
      type=3 
    },
    {
      Content="我的名字是<color=#B5A642ff>零</color>，是这里的一名图书馆员（librarian）。",
      EndFun="",
      Name="？？？",
      NextStep=5,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="这个图书馆的馆长——科斯莫斯，让我在这里等你，但我在等待的时间里睡着了，这是我的失态。",
      EndFun="",
      Name="零",
      NextStep=6,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="科斯莫斯跟我说，你入馆之后似乎因为“视界”过于开阔，接收了太多信息，以至于你的记忆和认知在短期内产生了一些错乱。",
      EndFun="",
      Name="零",
      NextStep=7,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="因此，他嘱咐我照看你，直到你恢复为止。",
      EndFun="",
      Name="零",
      NextStep=8,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="接下来，将会由我负责引导你在图书馆内完成审核和登记。",
      EndFun="",
      Name="零",
      NextStep=9,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="在这期间内，我会在我被允许的范围内解答你的所有疑问。",
      EndFun="",
      Name="零",
      NextStep=10,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      CloseGrey={  },
      EndFun="",
      Grey=100,
      NextStep=11,
      OpenGrey={ 7 },
      StartFun="",
      Type="剧情灰",
      type=10 
