      NextStep=17,
      OpenGrey={  },
      StartFun="",
      Type="剧情灰",
      type=10 
    },
    {
      Content="每一名巴别图书馆的访客都需要在这个地方留下自己的档案。",
      EndFun="",
      Name="零",
      NextStep=18,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="献上自己的“知识”，获得使用这里的权利，这是我们和图书馆长久以来默认的契约。",
      EndFun="",
      Name="零",
      NextStep=19,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="你的基本资料我已经收到了，但是更多关于你的信息还需要进一步登录。",
      EndFun="",
      Name="零",
      NextStep=20,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="在完成了所有仪式后，你就是我们的一员了。",
      EndFun="",
      Name="零",
      NextStep=14,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      CloseGrey={ 7 },
      EndFun="",
      Grey=100,
      NextStep=22,
      OpenGrey={  },
      StartFun="",
      Type="剧情灰",
      type=10 
    },
    {
      Content="如果你是问地理坐标的话，我可以告诉你具体信息，我们现在位于东经15度，北纬38度。",
      EndFun="",
      Name="零",
      NextStep=23,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="但是我们正在移动，如果一个小时后你问我同样问题，我不能保证还能回答相同的数字。",
      EndFun="",
      Name="零",
      NextStep=24,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="这里灵泊·巴别图书馆。正如其名，这里是一个图书馆——拥有无尽房间和书卷的图书馆。",
      EndFun="",
      Name="零",
      NextStep=25,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="同时，这里是楔文会（Eme-an）的本部。但也有人将这里称之为C.A.V.E的中央信息库，因为这里收容了自古以来人类文明的所有知识。",
      EndFun="",
      Name="零",
      NextStep=26,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      CloseGrey={  },
      EndFun="",
      Grey=100,
      NextStep=27,
      OpenGrey={ 7 },
      StartFun="",
      Type="剧情灰",
      type=10 
    },
    {
      EndFun="",
      NextStep=0,
      StartFun="",
      Type="剧情分支",
      content={ "楔文会和C.A.V.E？", "", "" },
      go_step={ 28 },
      type=6 
    },
    {
      CloseGrey={ 7 },
      EndFun="",
      Grey=100,
      NextStep=29,
      OpenGrey={  },
      StartFun="",
      Type="剧情灰",
      type=10 
    },
    {
      Content="……你看起来对你的现状一无所知。",
      EndFun="",
      Name="零",
      NextStep=30,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="<color=#B5A642ff>C.A.V.E</color>——全称“异象实体管制联盟”，是由十二个不同的组织构成的秘盟。",
      EndFun="",
      Name="零",
      NextStep=31,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="秘盟存在于世的目的是观测我们的世界，并在有违我们世界逻辑的异象实体入侵时予以干涉，以保证我们的世界维持住应有的世界理型，以合理的逻辑存续。",
      EndFun="",
      Name="零",
      NextStep=32,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="楔文会作为C.A.V.E的一员，一直以来负责管理着这个图书馆。",
      EndFun="",
      Name="零",
      NextStep=33,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="只有C.A.V.E的成员有资格进入图书馆，同样的，每一名加入C.A.V.E的成员都应当在图书馆内留下自己的一切信息，这是C.A.V.E在成立的时候立下的盟约。",
      EndFun="",
      Name="零",
      NextStep=34,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="基础资料显示，你是在C.A.V.E偶然的一次公开招募中，被发现了作为“预见者”的潜质。",
      EndFun="",
      Name="零",
      NextStep=35,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
