      NextStep=76,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="只是稍微放缓脚步，和她的距离又像是被无限拉远。",
      EndFun="",
      Name="",
      NextStep=77,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="走在前面的少女忽然站定。",
