      RolePos=3,
      StartFun="",
      Type="角色出现",
      type=3 
    },
    {
      Content="待在我身边，不要离我太远，不然你会迷失在这个空间里。",
      EndFun="",
      Name="零",
      NextStep=80,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="你还没有完成入馆的“仪式”，图书馆现在并不欢迎你。",
      EndFun="",
      Name="零",
      NextStep=81,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="在她的措辞中，这个图书馆就像是一个拥有自我意识的活物。",
      EndFun="",
      Name="",
      NextStep=82,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="“图书馆是活物，图书馆自有其智慧。”",
      EndFun="",
      Name="零",
      NextStep=83,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="——这是第一代馆长埃利什，曾经说过的话。",
      EndFun="",
      Name="零",
      NextStep=84,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="因此，访客应当在图书馆内保持安静、谦虚和谨慎。",
      EndFun="",
      Name="零",
      NextStep=85,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="不可妄言，不可妄书，不可妄想，盖因言语有力量，文字有力量，思考亦有力量。",
      EndFun="",
      Name="零",
      NextStep=86,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="说完，她转过身，朝我的方向伸出了手。",
      EndFun="",
      Name="",
      NextStep=87,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="什么都不要去思考，只要跟着我就行了。",
      EndFun="",
      Name="零",
      NextStep=88,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="诚如她所言，言语确实拥有力量。",
