      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="那是学者穷尽毕生言语都无法阐述的抽象形状，他隐隐之中意识到了自己接触到了某个至高的存在，但是仅仅只是惊鸿一睹，所有的一切又消失了。",
