      NextStep=131,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="只是不知为何，中央静置着一个空无一物的石架，一支芦苇笔，和一块又一块湿润的泥板。",
