      Name="",
      NextStep=138,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="而后，他将写完的第一块泥板放在石架上。然而望着摆放在石架上的泥板，学者心中的空虚却仍未消解。",
