      Type="普通对话",
      type=5 
    },
    {
      Content="曾有一位哲人认为——自然界中所有有形之物都是流动的，世间没有不会分解的物质。",
      EndFun="",
      Name="零",
      NextStep=20,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="但是形成有形之物的或“形式”却是永恒不变的。",
      EndFun="",
      Name="零",
      NextStep=21,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="也就是物质世界的背后，必然有一个实在且永恒不变的模板，这就是“理型”，是所有客观现实存在的基础。",
      EndFun="",
      Name="零",
      NextStep=22,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="有形之物如果不身处于自己应在的物质世界中，形成自己的物质就会逐渐消散，这就是“回归”。",
      EndFun="",
      Name="零",
      NextStep=23,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="我们身处的巴别图书馆，是两个世界的交汇之地，是不稳定之处（Limbo）。",
      EndFun="",
      Name="零",
      NextStep=24,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="并不完全是对方的世界，也并不完全是我们的世界，因此一切都处于一个暧昧模糊的状态。",
      EndFun="",
      Name="零",
      NextStep=25,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="如果两个世界的理型接近，调律就是稳定的，双方就能保持共存。",
      EndFun="",
      Name="零",
      NextStep=26,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="但是如果双方的理型相异，调律是不稳定的，弱的一方的理型就会率先崩溃。事物的模型崩溃，灌注在模子里的物质本身自然也会消散。",
      EndFun="",
      Name="零",
      NextStep=27,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="因为图书馆是比我们更高维度的世界，因此它对我们拥有更好的兼容力——灵泊的调律指数更高。",
      EndFun="",
      Name="零",
      NextStep=28,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="但是现在这份稳定被打破了，不知道是被谁，也不知道是用什么手段。",
