      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="但是有极少一部分人，也就是<color=#B5A642ff>视界</color>更高的人，不会立刻受此影响，依然能在这种情况下保持自己的理型和存在的物质。",
