      NextStep=101,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="既然你已经“看见”过那块黑碑，那么我跟你以下讲的内容，你应该可以更容易理解。",
      EndFun="",
      Name="零",
      NextStep=102,
