      Name="零",
      NextStep=104,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="一个将另一个维度的世界的一部分，和我们的世界的一部分短暂地交叠在一起的媒介。",
      EndFun="",
      Name="零",
      NextStep=105,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="而世界与世界重叠交织的这个空间，我们如今将其称之为灵泊。",
      EndFun="",
      Name="零",
      NextStep=106,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="信标不止一个，这样的空间也不止一处。",
      EndFun="",
      Name="零",
      NextStep=107,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="其中，埃利什所发掘的灵泊，正是我们如今身处的巴别图书馆的前身。",
      EndFun="",
      Name="零",
      NextStep=108,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="而他本人，也成为了图书馆的第一任馆长。",
      EndFun="",
      Name="零",
      NextStep=109,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="他于此之上兴建了大神庙，将信标掩藏其中，并切创立了一个组织，借此倾听来自欧贝德帝国四方的旅人的祈祷，以确认世上是否还有其余地方有着同样的石碑，发生着相同的神迹。",
      EndFun="",
      Name="零",
      NextStep=110,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="后来，这个组织的人自发以艾弥安自称，意为“神的喉舌”。",
