      Name="零",
      NextStep=151,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="无论如何，当我们世界的理型越来越丰满之后，有违我们世界逻辑的东西就退出历史的舞台。",
      EndFun="",
      Name="零",
      NextStep=152,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="学会了生火后，人便不再信仰火神。",
      EndFun="",
      Name="零",
      NextStep=153,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="登上了太空后，人便不再相信天堂。",
