      NextStep=155,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="经历了漫长的光阴，拥有极高视界的人们逐渐认识到，无论灵泊及其内的事物来自何方，它们都不应当成为人类文明前进道路上的阻碍或干扰。",
