      Name="零",
      NextStep=156,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="于是这些人决定观察着信标和灵泊，并且在它会危害人类的世界的时候进行干涉。",
