      Name="伊蕾什安",
      NextStep=41,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="但是有一天，他带回来了一无所有的你，于是我的一切全部都被你抢走了。",
