      Name="伊蕾什安",
      NextStep=52,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="假使有一天人类能够解析未知，那么神秘也就不复存在，归根结底，“神”只要能被阐明，就只是一些无趣的东西罢了。",
