      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="这个宇宙中没有任何人类概念中的物质和能量。这里的法则以我们不了解的规则构建世界。自然，也就谈不上有任何我们可认知形式的生命。",
