      Name="伊蕾什安",
      NextStep=55,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="但是，这个宇宙中的确有某种“存在”，某种已经纯能化的生命体，只是它并不渴求物质与能量，它渴求外界的信息与知识。",
