      Name="伊蕾什安",
      NextStep=56,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="理所当然，它需要化作我们可以认知的形式来和我们“交流”，来从我们这里汲取“养分\"，再用穷举法来完善自己的生命形式。",
      EndFun="",
      Name="伊蕾什安",
      NextStep=57,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="这就是图书馆的真相，这就是所谓的智慧之神的本体。",
      EndFun="",
      Name="伊蕾什安",
      NextStep=58,
      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="说到底，图书馆就是这样无趣的东西。",
