      StartFun="",
      TalkPos={ [3]=true },
      Type="普通对话",
      type=5 
    },
    {
      Content="然而我们却要为这样简单粗暴的存在奉献自己的一生，只是为了从无限的排列组合里找寻对未来的预言，探寻所谓的真理。",
