      EndFun="",
      NextStep=12,
      StartFun="",
      TalkList={
        "祭司们说，物皆有名，名皆有力。名赋物形，形锢物灵。",
        "只需呼唤假太阳之名，即可使它回到天空。",
        "\
法老命祭司们呼唤拉、荷鲁斯、阿图姆、凯布利、阿蒙之名。",
        "假太阳毫无回应。",
        "\
自然，这些是真太阳之名，假太阳怎么可能配得上这些名字？",
        "\
