      EndFun="",
      NextStep=13,
      StartFun="",
      TalkList={
        "祭司颇泰赫命令工匠完成法老的要求。",
        "我不愿做此等亵渎之事，然而众神远在芦苇原彼岸，法老的刀斧手却近在眼前。",
