      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="法老在位第二十五年，我过去的同仁塔哈尔卡叛乱，夜间私自带兵入侵法老寝宫。",
      EndFun="",
      Name="",
      NextStep=34,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="法老下令我们除去叛军，我们执行了命令，愿九神湮灭塔哈尔卡虚伪的心脏。",
