      StartFun="",
      Type="切换背景动画",
      type=2 
    },
    {
      BeginDelay=1000,
      Content="次日，阿顿升起，照耀天空，法老在永世之河中沐浴，举行盛大的庆典。",
      EndFun="",
      Name="",
      NextStep=37,
      StartFun="screen_fade_out",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="正午时分，法老登上高台，阿顿运行至中天，法老伸出双手，念诵从未有人听过的奇怪咒语，听来很像“阿阿顿阿顿阿顿顿阿阿顿阿阿顿”。",
      EndFun="",
      Name="",
      NextStep=38,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="从未有人见过的奇迹随后出现，阿顿的光芒如孔雀尾羽一般收拢，天空暗淡，群星浮现。",
      EndFun="",
      Name="",
      NextStep=39,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="收拢的光芒洒向高台，整个埃赫塔顿之内，唯有法老一人独享太阳的照耀。",
      EndFun="",
      Name="",
      NextStep=40,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="我见到，照耀于高台上的光束再度收拢，集于法老之身。",
      EndFun="",
      Name="",
      NextStep=41,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="光束之中，仿佛有一只手自阿顿缓缓伸下，直至触碰法老的身体。",
      EndFun="",
      Name="",
      NextStep=42,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="我见到，触碰的瞬间，法老开始燃烧，他停止念诵咒语，发出痛苦的哀嚎，随后化作袅袅飞灰。",
      EndFun="",
      Name="",
      NextStep=43,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="没有人敢走进光芒之中，因为光芒中的地面开始熔化，变成铁水一般的红色。",
      EndFun="",
      Name="",
      NextStep=44,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="无人数得清这些手的数目，也许有一百只，一千只，或一万只。",
      EndFun="",
      Name="",
      NextStep=45,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="阿顿之手带来死亡、恐怖与毁灭。",
