      NextStep=48,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="祭司们认为我已精神失常，打发我去与病人们同住，在这乌烟瘴气的房间里，我写下这些词句，希冀它们可以流传后世。",
