      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="曾经有一群囚犯，从小就被捆绑着身子，面朝洞壁坐在一个山洞之中。",
      EndFun="",
      Name="科斯莫斯",
      NextStep=55,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="他们无法回头，看不见洞穴的出口，也看不见自己与别的囚犯。",
      EndFun="",
      Name="科斯莫斯",
      NextStep=56,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="终其一生， 所能见到的只有面前的墙壁。",
      EndFun="",
      Name="科斯莫斯",
      NextStep=57,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="洞穴之外，是耀眼的太阳，太阳的光芒普照一切。洞穴之外的物体，受太阳的恩泽，将自身的阴影投射在洞穴的墙壁之上。",
      EndFun="",
      Name="科斯莫斯",
      NextStep=58,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="囚犯们看见了这些移动的光影，便以为它们是真正的生物。",
      EndFun="",
      Name="科斯莫斯",
      NextStep=59,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="它们以为这些影子，构成了真正的世界。",
      EndFun="",
      Name="科斯莫斯",
      NextStep=60,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="他们甚至为这些影子的行动整理了一套规律，预告将要发生的事情。",
      EndFun="",
      Name="科斯莫斯",
      NextStep=61,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="然而有一天，一些囚犯挣脱了束缚，来到了洞穴之外的世界。",
      EndFun="",
      Name="科斯莫斯",
      NextStep=62,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="你觉得，当这些囚犯看到真正的“太阳”时……",
      EndFun="",
      Name="科斯莫斯",
      NextStep=63,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="会发生什么？",
      EndFun="",
      Name="科斯莫斯",
      NextStep=64,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="不用回答我的问题，【BBNAME】。",
