      Name="",
      NextStep=6,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="圆桌会议本应是平等的会议形式，但是圆桌的一端却存在着一个特殊的座椅。",
      EndFun="",
