      NextStep=7,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="那张椅子远比其他椅子更加高大和古朴，它背朝着所有参会者，椅背上的纹路古拙庄重。",
      EndFun="",
      Name="",
      NextStep=8,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="这是一张永远不会转过来的椅子，但是无人会对此有任何异议,即便他们无从得知主座上坐着的究竟是谁……甚至是否有人。",
      EndFun="",
      Name="",
      NextStep=9,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
