    },
    {
      Content="主座上传来的声音如同是机械的合成音——毫无特色，机械、平板、不带一丝感情色彩，甚至分辨不清性别。",
      EndFun="",
      Name="",
      NextStep=13,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="所有人同时向主座微微颔首示意。",
      EndFun="",
      Name="",
      NextStep=14,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="诸行必果，诸债必偿。",
      EndFun="",
      Name="所有人",
      NextStep=15,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="机械音发出了一声喟叹。",
      EndFun="",
      Name="",
      NextStep=16,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="我们有段时日不曾像这样聚在一起了",
      EndFun="",
      Name="<color=#ff4e4eff>报应者</color>",
      NextStep=17,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="希望这段时间里，诸位的事业都得遂所愿。",
      EndFun="",
      Name="<color=#ff4e4eff>报应者</color>",
      NextStep=18,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="召集这次会议，是因为我们静候已久的时机终于到来了，现在——",
      EndFun="",
      Name="<color=#ff4e4eff>报应者</color>",
      NextStep=19,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="机械音顿了顿，话音一转。",
      EndFun="",
      Name="",
      NextStep=20,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="我听到了海浪的声音，<color=#ff4e4eff>不归者</color>，是你吗？",
      EndFun="",
      Name="<color=#ff4e4eff>报应者</color> ",
      NextStep=21,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="半晌，一名女性的声音回应了报应者的提问。",
      EndFun="",
      Name="",
      NextStep=22,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="是的。",
      EndFun="",
      Name="不归者",
      NextStep=23,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="女人的声音宛如来自深海的回响，悠远绵长。语末的余音中有海浪的回声，像是她此时此刻整漂泊在汪洋的中央。",
      EndFun="",
      Name="",
      NextStep=24,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="恕我以这样的姿态参加这场聚会，无锚之船无法在任何港口停泊。",
      EndFun="",
      Name="不归者",
      NextStep=25,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="一个苍老的声音响起。",
      EndFun="",
      Name="",
      NextStep=26,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="你需要信念，<color=#ff4e4eff>不归者</color>。",
      EndFun="",
      Name="殉道者",
      NextStep=27,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="信念揭示归途，可以让漂泊的人找到自己最终的航向。",
      EndFun="",
      Name="殉道者",
      NextStep=28,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="他的声音中夹杂着某种模糊的旋律，像唱诗班的吟诵，声音也沾染上了些许圣洁的意味。",
      EndFun="",
      Name="",
      NextStep=29,
      StartFun="",
      TalkPos={ true },
      Type="普通对话",
      type=5 
    },
    {
      Content="谢谢你，<color=#ff4e4eff>殉道者</color>。",
      EndFun="",
      Name="不归者",
      NextStep=30,
      StartFun="",
      TalkPos={ true },
      Type="普通对话",
      type=5 
    },
    {
      Content="尽管是在道谢，然而女人的声音却如海水一样冰冷。",
      EndFun="",
      Name="",
      NextStep=31,
      StartFun="",
      TalkPos={ true },
      Type="普通对话",
      type=5 
    },
    {
      Content="不过还是将你的祈祷与弥撒留给陆上的众人吧，海洋是你所信仰的天上之父不及之处。",
      EndFun="",
      Name="不归者",
      NextStep=32,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="被称为“殉道者”的人影似乎还想说点什么，但是机械音打断了他的话。",
      EndFun="",
      Name="",
      NextStep=33,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="殉道者，你的“布道”进展如何？",
      EndFun="",
      Name="<color=#ff4e4eff>报应者</color>",
      NextStep=34,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="殉道者从自己的位置上站了起来，微微朝主座欠身。",
      EndFun="",
      Name="",
      NextStep=35,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="计划很顺利。",
      EndFun="",
      Name="殉道者",
      NextStep=36,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="花之都的僭主已死，教廷也已群龙无首，他们很快将选举下一任教宗。",
      EndFun="",
      Name="殉道者",
      NextStep=37,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="权利的争夺已经席卷雅弗神圣帝国，铂鸢家族的新家主在这场洪流之中自顾不暇。",
      EndFun="",
      Name="殉道者",
      NextStep=38,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="纵然这个家族曾经控制半数帝国的军事力量，但是现在每个司令和将军都在等待着国内局势的尘埃落定。",
      EndFun="",
      Name="殉道者",
      NextStep=39,
      StartFun="",
      TalkPos={ true },
      Type="普通对话",
      type=5 
    },
    {
      Content="无人回应那位年轻公爵的号召，她已经没有余力来关心我们即将制造的小小“动乱”。",
      EndFun="",
      Name="殉道者",
      NextStep=40,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="无机质的声音对这个消息给予了自己的肯定。",
      EndFun="",
      Name="",
      NextStep=41,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="你的“福音”总是令人感到欢悦。",
      EndFun="",
      Name="<color=#ff4e4eff>报应者</color>",
      NextStep=42,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="这是我应尽的使命。",
      EndFun="",
      Name="殉道者",
      NextStep=43,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="身影再次朝主座欠身，然后坐下。",
      EndFun="",
      Name="",
      NextStep=44,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="陆上的一切正如计划那般向前推进，我们的夙愿已逐渐化作现实，它将成为碾过历史的钢铁之轮，没有任何东西能从车轮下幸免。",
      EndFun="",
      Name="殉道者",
      NextStep=45,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="只是不知道在那片车轮无法行进的海洋上，一切又是否如同我们一样顺遂？",
      EndFun="",
      Name="殉道者",
      NextStep=46,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="不归者轻笑了一声。",
