      Name="不归者",
      NextStep=50,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="它温和中庸，却拥有这个世界上最明智的“大脑”，它们是否会察觉到即将到来的风暴——这才是我所担忧的变数。",
      EndFun="",
      Name="不归者",
      NextStep=51,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="一个敦厚的声音回答了她的忧虑。",
