      NextStep=54,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="我简单概述一下我这里的情况，“乾”即将面临危机，这危机覆盖整个浩荡江流域。",
      EndFun="",
      Name="播种者",
      NextStep=55,
      StartFun="",
      TalkPos={ true },
      Type="普通对话",
      type=5 
    },
    {
      Content="唯实社没有时间去关心一支远在天边的舰队，而C.A.V.E本身也绝非表面上看起来那样团结。",
