      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="她是宏伟舰队的君王，但在风暴面前，她的舰队犹如孩子放入池塘的纸船一般脆弱，而她本人与徒劳地拍打翅膀的渡鸦无异。",
      EndFun="",
      Name="不归者",
      NextStep=62,
      StartFun="",
      TalkPos={ true },
      Type="普通对话",
      type=5 
    },
    {
