      Name="<color=#ff4e4eff>报应者</color>",
      NextStep=63,
      StartFun="",
      TalkPos={ true },
      Type="普通对话",
      type=5 
    },
    {
      Content="我们的准备的最后一步……<color=#ff4e4eff>博学者</color>，不归者所需的东西你准备好了吗？",
