      NextStep=73,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="我会的。",
      EndFun="",
      Name="不归者",
      NextStep=74,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="一切艺术形式中最美妙的莫过于歌颂毁灭的悲剧，我很久前就已经为这一幕准备好了剧本。",
      EndFun="",
      Name="不归者",
      NextStep=75,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="但请容我再问一句，之前会议上豪华者曾通报过的那件事……",
