      Name="不归者",
      NextStep=77,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="你只需知道这个人将为你们扫平在图书馆中前进的一切障碍。",
      EndFun="",
      Name="<color=#ff4e4eff>报应者</color>",
      NextStep=78,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="这个人还准备了一件足以摧毁巴别图书馆“武器”。豪华者的情报足够可靠，无须担心。",
      EndFun="",
      Name="<color=#ff4e4eff>报应者</color>",
      NextStep=79,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="我明白了。",
