      NextStep=84,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="哦、噢——终于轮到我了是吗？",
      EndFun="",
      Name="豪华者",
      NextStep=85,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="他的声音没有经过任何处理，拥有着一个年轻男性特有的爽朗，甚至带着点格格不入的吊儿郎当。",
      EndFun="",
      Name="",
      NextStep=86,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="没问题，请放心地将一切交给我。",
