      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="我知道在座的各位都是各自社会里数一数二的体面人，肯定不希望自己参加一个可疑聚会的花边新闻出现在报纸头条上！",
