      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
    },
    {
      Content="无论你们是以何种形式参加了这场聚会：投影、声音，亦或是本人到场……都不必担心。",
      EndFun="",
      Name="豪华者",
      NextStep=89,
      StartFun="",
      TalkPos={  },
      Type="普通对话",
      type=5 
